ers_url":"https://api.github.com/users/boschtech/followers","following_url":"https://api.github.com/users/boschtech/following{/other_user}","gists_url":"https://api.github.com/users/boschtech/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/boschtech","id":198587710,"login":"boschtech","node_id":"U_kgDOC9Y1Pg","organizations_url":"https://api.github.com/users/boschtech/orgs","received_events_url":"https://api.github.com/users/boschtech/received_events","repos_url":"https://api.github.com/users/boschtech/repos","site_admin":false,"starred_url":"https://api.github.com/users/boschtech/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/boschtech/subscriptions","type":"User","url":"https://api.github.com/users/boschtech","user_view_type":"public"},"comments_url":"https://api.github.com/repos/boschtech/ui-playwright-automation/commits/fb6a1c287ea6148175df46590e8bc0b290c9b81a/comments","commit":{"author":{"date":"2026-04-16T17:03:39Z","email":"admin@boschtechnologies.com","name":"boschtech"},"comment_count":0,"committer":{"date":"2026-04-16T17:03:39Z","email":"admin@boschtechnologies.com","name":"boschtech"},"message":"test(playwright): bump CI workers from 1 to 10\n\nRun the e2e suite with 10 parallel workers in CI to shorten feedback\ntime. Local runs remain on Playwright''s default (cores/2).\n\nCo-Authored-By: Oz <oz-agent@warp.dev>","tree":{"sha":"5fe18880ae0305fcd9f1150078b181edbaaf912e","url":"https://api.github.com/repos/boschtech/ui-playwright-automation/git/trees/5fe18880ae0305fcd9f1150078b181edbaaf912e"},"url":"https://api.github.com/repos/boschtech/ui-playwright-automation/git/commits/fb6a1c287ea6148175df46590e8bc0b290c9b81a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/198587710?v=4","events_url":"https://api.github.com/users/boschtech/events{/privacy}","followers_url":"https://api.github.com/use